import arcjet, { detectBot, fixedWindow } from "@arcjet/next";
import { NextResponse } from "next/server";

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  rules: [
    detectBot({ mode: "LIVE", allow: ["CATEGORY:SEARCH_ENGINE"] }),
    fixedWindow({ mode: "LIVE", window: "1m", max: 10 }),
  ],
});

export async function GET(req: Request) {
  const decision = await aj.protect(req);
  if (decision.isDenied()) return new NextResponse("Denied", { status: 403 });
  if (decision.isChallenge()) return new NextResponse("Challenge", { status: 401 });
  if (decision.isError()) return new NextResponse("Temporarily unavailable", { status: 503 });
  return NextResponse.json({ ok: true });
}

