import { createMiddleware } from "@arcjet/next";
import arcjet, { shield } from "@arcjet/next";
import { z } from "zod";

const bodySchema = z.object({ name: z.string() });

const validateBody = {
  type: "CUSTOM",
  name: "validate-body",
  validate: async ({ request }) => {
    const body = await request.json();
    return bodySchema.safeParse(body).success
      ? { conclusion: "ALLOW" }
      : { conclusion: "DENY", reason: "Invalid body" };
  },
};

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  rules: [shield({ mode: "LIVE" }), validateBody],
});

export default createMiddleware(async (req) => {
  const decision = await aj.protect(req);
  if (decision.isDenied()) return new Response("Forbidden", { status: 403 });
});

import arcjet, { detectBot, validateEmail } from "@arcjet/next";

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  rules: [
    validateEmail({
      mode: "LIVE",
      deny: ["DISPOSABLE", "NO_MX_RECORDS", "INVALID"],
    }),
  ],
});

export async function POST(req: Request) {
  const { email } = await req.json();
  const decision = await aj.protect(req, { email });

  if (decision.isDenied()) {
    return new Response("Invalid email", { status: 400 });
  }
  return new Response("Accepted", { status: 200 });
}

